def _parse_features(cls, feat_response):
        # type: (Text) -> Dict[Text, Text]
        """Parse a dict of features from FTP feat response.
        """
        feats = {}
        for line in feat_response.splitlines():
            if line.startswith(' '):
                feats[feats.keys()[-1]] += ' ' + line.strip()
            else:
                feats[line.strip()] = ''
        return feats

